    if (!Number.isInteger(line.qty) || line.qty <= 0) return fail('QTY_INVALID');

    // Validate discount percent if provided
    if (line.discountPercent !== undefined && !isValidDiscountPercent(line.discountPercent)) {
      return fail('DISCOUNT_INVALID');
    }

    // Validate SKU exists and get product details
    const productResult = getProduct(line.sku);
    if (!productResult.ok) return productResult;

    const product = productResult.value;
    const newLine = {
      sku: line.sku,
      name: product.name,
      qty: line.qty,
      unitPrice: product.unitPrice,
      vatRate: product.vatRate,
    };

    // Apply discount: line's own discountPercent wins, otherwise use tier discount
    if (line.discountPercent !== undefined) {
      newLine.discountPercent = line.discountPercent;
    } else {
      const tierDiscount = TIER_DISCOUNTS[customer.tier];
      if (tierDiscount > 0) {
        newLine.discountPercent = tierDiscount;
      }
    }

    invoiceLines.push(newLine);
  }

  const dueDate = calculateDueDate(issueDate, terms);

  const invoice = {
    customerId: normalizedCustomerId,
    issueDate,
    status: 'draft',
    lines: invoiceLines,
    terms,
    dueDate,
  };

  return ok(invoice);
}

/**
 * Calculate the total for a single line item (qty × unitPrice, rounded to cents).
 * @param {{ sku: string, name: string, qty: number, unitPrice: number, vatRate: number, discountPercent?: number }} line
 * @returns {number}
 */
export function lineTotal(line) {
  return roundCents(line.qty * line.unitPrice);
}

/**
 * Calculate the discount amount for a single line item.
 * @param {{ sku: string, name: string, qty: number, unitPrice: number, vatRate: number, discountPercent?: number }} line
 * @returns {number}
 */
export function lineDiscount(line) {
  if (line.discountPercent === undefined) return 0;
  const total = lineTotal(line);
  const discount = roundCents(total * line.discountPercent / 100);
  return Math.max(0, discount);
}

/**
 * Calculate the VAT amount for a single line item.
 * VAT is computed on the line amount after its discount.
 * @param {{ sku: string, name: string, qty: number, unitPrice: number, vatRate: number, discountPercent?: number }} line
 * @returns {number}
 */
export function lineVAT(line) {
  const total = lineTotal(line);
  const discount = lineDiscount(line);
  const taxableAmount = total - discount;
  const vat = roundCents(taxableAmount * line.vatRate / 100);
  return Math.max(0, vat);
}

/**
 * Calculate totals for an invoice.
 * @param {{ customerId: string, issueDate: string, status: string, lines: Array, voucher?: object }} invoice
 * @returns {{ subtotal: number, discount: number, vat: number, voucher: number, total: number }}
 */
export function invoiceTotals(invoice) {
  const subtotal = invoice.lines.reduce((sum, line) => sum + lineTotal(line), 0);
  const discount = invoice.lines.reduce((sum, line) => sum + lineDiscount(line), 0);
  const vat = invoice.lines.reduce((sum, line) => sum + lineVAT(line), 0);
  const voucher = invoice.voucher ? invoice.voucher.amount : 0;
  const total = Math.max(0, subtotal - discount + vat - voucher);
  return {
    subtotal,
    discount,
    vat,
    voucher,
    total,
  };
}

/**
 * Add or increase a line on an invoice.
 * @param {{ customerId: string, issueDate: string, status: string, lines: Array }} invoice
 * @param {{ sku: string, qty: number, discountPercent?: number }} params
 * @returns {{ ok: true, value: object } | { ok: false, error: string }}
 */
export function addLine(invoice, { sku, qty, discountPercent }) {
  // Check status is draft
  if (invoice.status !== 'draft') return fail('NOT_DRAFT');

  // Validate qty is a positive integer
  if (!Number.isInteger(qty) || qty <= 0) return fail('QTY_INVALID');

  // Validate discount percent if provided
  if (discountPercent !== undefined && !isValidDiscountPercent(discountPercent)) {
    return fail('DISCOUNT_INVALID');
  }

  // Validate SKU exists and get product details
  const productResult = getProduct(sku);
  if (!productResult.ok) return productResult;

  const product = productResult.value;
  const newLines = invoice.lines.map((line) => ({ ...line }));

  // Check if SKU already exists
  const existingLineIndex = newLines.findIndex((line) => line.sku === sku);
  if (existingLineIndex >= 0) {
    // Increase qty on existing line
    const updatedLine = {
      ...newLines[existingLineIndex],
      qty: newLines[existingLineIndex].qty + qty,
    };
    if (discountPercent !== undefined) {
      updatedLine.discountPercent = discountPercent;
    }
    newLines[existingLineIndex] = updatedLine;
  } else {
    // Add new line
    const newLine = {
      sku,
      name: product.name,
      qty,
      unitPrice: product.unitPrice,
      vatRate: product.vatRate,
    };
    if (discountPercent !== undefined) {
      newLine.discountPercent = discountPercent;
    }
    newLines.push(newLine);
  }

  const newInvoice = {
    ...invoice,
    lines: newLines,
  };

  return ok(newInvoice);
}

/**
 * Remove a line from an invoice.
 * @param {{ customerId: string, issueDate: string, status: string, lines: Array }} invoice
 * @param {string} sku
 * @returns {{ ok: true, value: object } | { ok: false, error: string }}
 */
export function removeLine(invoice, sku) {
  // Check status is draft
  if (invoice.status !== 'draft') return fail('NOT_DRAFT');

  // Check if SKU exists on invoice
  const lineIndex = invoice.lines.findIndex((line) => line.sku === sku);
  if (lineIndex < 0) return fail('LINE_NOT_FOUND');

  // Check if this is the last line
  if (invoice.lines.length === 1) return fail('NO_LINES');

  // Create new lines array without the target SKU
  const newLines = invoice.lines.filter((line) => line.sku !== sku);

  const newInvoice = {
    ...invoice,
    lines: newLines,
  };

  return ok(newInvoice);
}

/**
 * Issue an invoice (change status from draft to issued and assign a number).
 * @param {{ customerId: string, issueDate: string, status: string, lines: Array }} invoice
 * @param {string[]} existingNumbers - Array of invoice numbers already used
 * @returns {{ ok: true, value: object } | { ok: false, error: string }}
 */
export function issueInvoice(invoice, existingNumbers) {
  // Check status is draft
  if (invoice.status !== 'draft') return fail('NOT_DRAFT');

  // Get the next invoice number
  const number = nextInvoiceNumber(existingNumbers, invoice.issueDate);

  const newInvoice = {
    ...invoice,
    number,
    status: 'issued',
  };

  return ok(newInvoice);
}

/**
 * Apply a voucher to an invoice.
 * @param {{ customerId: string, issueDate: string, status: string, lines: Array, voucher?: object }} invoice
 * @param {{ code: string, amount: number }} params
 * @returns {{ ok: true, value: object } | { ok: false, error: string }}
 */
export function applyVoucher(invoice, { code, amount }) {
  // Check status is draft
  if (invoice.status !== 'draft') return fail('NOT_DRAFT');

  // Check voucher doesn't already exist
  if (invoice.voucher) return fail('VOUCHER_EXISTS');

  // Check amount is a positive integer
  if (!Number.isInteger(amount) || amount <= 0) {
    return fail('AMOUNT_INVALID');
  }

  const newInvoice = {
    ...invoice,
    voucher: { code, amount },
  };

  return ok(newInvoice);
}

