  const invoice = {
    customerId: 'C-001',
    issueDate: '2025-10-07',
    status: 'draft',
    lines: [{ sku: 'DEV-HOUR', name: 'Development', qty: 5, unitPrice: 10000, vatRate: 21 }],
  };
  const totals = invoiceTotals(invoice);
  assert.equal(totals.voucher, 0);
});

test('invoiceTotals includes voucher in calculation', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2025-10-07',
    status: 'draft',
    lines: [{ sku: 'DEV-HOUR', name: 'Development', qty: 5, unitPrice: 10000, vatRate: 21 }],
    voucher: { code: 'PROMO', amount: 5000 },
  };
  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 50000);
  assert.equal(totals.discount, 0);
  assert.equal(totals.vat, 10500);
  assert.equal(totals.voucher, 5000);
  assert.equal(totals.total, 50000 - 0 + 10500 - 5000);
});

test('invoiceTotals total is clamped at zero with large voucher', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2025-10-07',
    status: 'draft',
    lines: [{ sku: 'DEV-HOUR', name: 'Development', qty: 5, unitPrice: 10000, vatRate: 21 }],
    voucher: { code: 'HUGE', amount: 1000000 },
  };
  const totals = invoiceTotals(invoice);
  assert.equal(totals.total, 0);
});

test('invoiceTotals with voucher and discounts', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2025-10-07',
    status: 'draft',
    lines: [
      { sku: 'DEV-HOUR', name: 'Development', qty: 5, unitPrice: 10000, vatRate: 21, discountPercent: 10 },
    ],
    voucher: { code: 'PROMO', amount: 2000 },
  };
  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 50000);
  assert.equal(totals.discount, 5000);
  const taxableAmount = totals.subtotal - totals.discount;
  const expectedVat = Math.round(taxableAmount * 0.21);
  assert.equal(totals.vat, expectedVat);
  assert.equal(totals.voucher, 2000);
  assert.equal(totals.total, taxableAmount + expectedVat - 2000);
});

test('invoiceTotals with multiple VAT rates', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2025-10-07',
    status: 'draft',
    lines: [
      { sku: 'DEV-HOUR', name: 'Development', qty: 5, unitPrice: 10000, vatRate: 21 },
      { sku: 'FOOD', name: 'Food', qty: 2, unitPrice: 5000, vatRate: 9 },
    ],
  };
  const totals = invoiceTotals(invoice);
  const line1Vat = lineVAT(invoice.lines[0]);
  const line2Vat = lineVAT(invoice.lines[1]);
  assert.equal(totals.vat, line1Vat + line2Vat);
  assert.equal(totals.total, 60000 + line1Vat + line2Vat);
});

test('invoiceTotals empty lines array', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2025-10-07',
    status: 'draft',
    lines: [],
  };
  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 0);
  assert.equal(totals.discount, 0);
  assert.equal(totals.vat, 0);
  assert.equal(totals.voucher, 0);
  assert.equal(totals.total, 0);
});

test('invoiceTotals all amounts are integers', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2025-10-07',
    status: 'draft',
    lines: [
      { sku: 'DEV-HOUR', name: 'Development', qty: 5, unitPrice: 10000, vatRate: 21, discountPercent: 10 },
      { sku: 'DESIGN-HOUR', name: 'Design', qty: 3, unitPrice: 8000, vatRate: 21, discountPercent: 5 },
    ],
    voucher: { code: 'PROMO', amount: 2000 },
  };
  const totals = invoiceTotals(invoice);
  assert.ok(Number.isInteger(totals.subtotal));
  assert.ok(Number.isInteger(totals.discount));
  assert.ok(Number.isInteger(totals.vat));
  assert.ok(Number.isInteger(totals.voucher));
  assert.ok(Number.isInteger(totals.total));
});

