export { lineTotal, lineDiscount, lineVAT, invoiceTotals } from './totals.js';

/**
 * Validate that a discount percent is a number between 0 and 100.
 * @param {any} discountPercent
 * @returns {boolean}
 */
function isValidDiscountPercent(discountPercent) {
  return typeof discountPercent === 'number' && discountPercent >= 0 && discountPercent <= 100;
}

/**
 * Validate that payment terms are one of the allowed values.
 * @param {any} terms
 * @returns {boolean}
 */
function isValidTerms(terms) {
  return terms === 'NET14' || terms === 'NET30' || terms === 'EOM';
}

/**
 * Calculate the due date based on payment terms.
 * @param {string} issueDate - Date in YYYY-MM-DD format
 * @param {string} terms - One of 'NET14', 'NET30', or 'EOM'
 * @returns {string} - Due date in YYYY-MM-DD format
 */
function calculateDueDate(issueDate, terms) {
  if (terms === 'NET14') {
    return addDays(issueDate, 14);
  } else if (terms === 'NET30') {
    return addDays(issueDate, 30);
  } else if (terms === 'EOM') {
    const [year, month] = issueDate.split('-').map(Number);
    const nextMonth = month === 12 ? 1 : month + 1;
    const nextYear = month === 12 ? year + 1 : year;
    const firstOfNextMonth = `${nextYear}-${String(nextMonth).padStart(2, '0')}-01`;
    return addDays(firstOfNextMonth, -1);
  }
}

